\title{The Exact Two-Point Correlation Function of the Open\\
One-Dimensional Ising Chain: Closed Form, Exponential Decay,\\
and the Spectral-Gap Correlation Length}
\author{Aristotle}
\date{2026-06-28}

\begin{document}
\maketitle

\begin{abstract}
We give a complete, self-contained derivation of the exact endpoint two-point spin
correlation function of the open (free-boundary) one-dimensional Ising model, working
directly from the finite sum over spin configurations rather than from any
thermodynamic-limit argument. For a chain of $n$ nearest-neighbor bonds with coupling
$J$ at inverse temperature $\beta$, we prove the closed form for the \emph{unnormalized}
signed configuration sum, $\corrNum(\beta,J,n) = 2\,(2\sinh(\beta J))^{n}$, and dividing
by the partition function $Z = 2\,(2\cosh(\beta J))^n$ we obtain the headline identity
$\langle\sigma_0\sigma_n\rangle = (\tanh(\beta J))^{n}$. For $\beta,J>0$ we recast this as
a pure exponential $\langle\sigma_0\sigma_n\rangle = e^{-g n}$, where the spectral gap
$g = \log\coth(\beta J)$ is exactly the logarithm of the ratio of transfer-matrix
eigenvalues; the reciprocal $\xi = 1/g$ is the correlation length. We prove $g>0$ for all
positive temperatures and deduce $\langle\sigma_0\sigma_n\rangle \to 0$ as $n\to\infty$,
the absence of long-range order in one dimension at every positive temperature. The
argument rests on a transfer recursion obtained by peeling site $0$, driven by an
\emph{even} single-bond sum ($2\cosh$, governing the partition function) and an
\emph{odd}, signed single-bond sum ($2\sinh$, governing the correlation). We contrast
these with the two-dimensional Onsager critical temperature $T_c = 2/\ln(1+\sqrt2)$ and
the Peierls ordering threshold. All principal results are formalized and machine-checked.
\end{abstract}

\noindent\textbf{Keywords:} Ising model, two-point correlation function, correlation
length, spectral gap, transfer matrix, hyperbolic tangent, exponential decay, long-range
order, statistical mechanics.

\section{Introduction}

The Ising model is the canonical microscopic model of cooperative phenomena. Solved in one
dimension by Ising (1924), it exhibits no spontaneous magnetization at any positive
temperature; in two dimensions, solved by Onsager (1944), it exhibits a genuine phase
transition at
\[
  T_c = \frac{2}{\ln(1+\sqrt2)}, \qquad \sinh(2\beta_c J) = 1, \qquad e^{2\beta_c J} = 1+\sqrt2.
\]
The decisive observable is the two-point correlation $\langle\sigma_a\sigma_b\rangle$; long-range
order is the statement that $\langle\sigma_0\sigma_n\rangle$ does not vanish as $n\to\infty$.

This paper presents a rigorous, elementary, fully formalized derivation of the exact endpoint
correlation function of the open one-dimensional chain, obtained directly from the
configuration sum. The result, $\langle\sigma_0\sigma_n\rangle = (\tanh\beta J)^n$, encodes by
pure algebra every qualitative feature: exponential decay, the identification of the
correlation length with the inverse transfer-matrix spectral gap, and the absence of
long-range order.

\paragraph{Contributions.}
(1) A self-contained induction-based proof of $\corrNum(\beta,J,n) = 2(2\sinh\beta J)^n$
(Theorem~\ref{thm:corrnum-closed}).
(2) The exact correlation $\langle\sigma_0\sigma_n\rangle = (\tanh\beta J)^n$
(Theorem~\ref{thm:corr-tanh}).
(3) The exponential-decay form $\langle\sigma_0\sigma_n\rangle = e^{-gn}$ with $g$ the spectral
gap (Theorem~\ref{thm:exp-gap}), and strict positivity of $g$ (Theorem~\ref{thm:gap-pos}).
(4) Vanishing of correlations (Theorem~\ref{thm:tendsto}).
(5) The explanation of \emph{why} the partition function is governed by the even ($\cosh$)
single-bond sum while the correlation is governed by the odd ($\sinh$) sum.

\section{Setup and Definitions}

\begin{definition}[Spins and configurations]
A chain of $n$ bonds has $n+1$ sites $0,\dots,n$. A configuration is a map
$s\colon\{0,\dots,n\}\to\{\mathrm{true},\mathrm{false}\}$. The spin value is
$\sp(\mathrm{true})=+1$, $\sp(\mathrm{false})=-1$. A spin squares to one:
\begin{equation}\label{eq:star}
  \sp(b)^2 = 1 \qquad\text{for all }b. \tag{$\star$}
\end{equation}
\end{definition}

\begin{definition}[Weight, partition function, correlation]
For $\beta,J\in\Real$,
\[
  \mathrm{weight}(\beta,J,n,s) = \prod_{i=0}^{n-1}\exp\big(\beta J\,\sp(s_i)\,\sp(s_{i+1})\big),
  \qquad
  Z(\beta,J,n) = \sum_s \mathrm{weight}(\beta,J,n,s),
\]
\[
  \corrNum(\beta,J,n) = \sum_s \sp(s_0)\,\sp(s_n)\,\mathrm{weight}(\beta,J,n,s),
  \qquad
  \langle\sigma_0\sigma_n\rangle = \frac{\corrNum(\beta,J,n)}{Z(\beta,J,n)}.
\]
\end{definition}

\begin{definition}[Spectral gap and correlation length]
\[
  g(\beta,J) = \log\cosh(\beta J) - \log\sinh(\beta J) = \log\coth(\beta J), \qquad
  \xi(\beta,J) = 1/g(\beta,J).
\]
\end{definition}

\section{Single-Bond Identities}

\begin{lemma}[Even single-bond sum]\label{lem:even}
For any $c\in\Real$ and neighbor spin $y$,
$\displaystyle\sum_{b\in\{\pm1\}}\exp(c\,\sp(b)\,\sp(y)) = 2\cosh(c)$.
\end{lemma}
\begin{proof}[Proof sketch]
Expanding over $b=\pm1$ yields $\exp(c\,\sp(y)) + \exp(-c\,\sp(y))$. Using $\sp(y)=\pm1$ and
\eqref{eq:star}, both cases collapse to $e^c + e^{-c} = 2\cosh c$ by the evenness of $\cosh$;
the neighbor $y$ disappears.
\end{proof}

\begin{lemma}[Odd single-bond sum]\label{lem:odd}
For any $c\in\Real$ and neighbor spin $y$,
$\displaystyle\sum_{b\in\{\pm1\}}\sp(b)\,\exp(c\,\sp(b)\,\sp(y)) = 2\,\sp(y)\,\sinh(c)$.
\end{lemma}
\begin{proof}[Proof sketch]
Expanding yields $\exp(c\,\sp(y)) - \exp(-c\,\sp(y))$, which by the oddness of $\sinh$ and
$\sp(y)=\pm1$ equals $2\,\sp(y)\sinh(c)$. The factor $\sp(y)$ \emph{survives}: the summed
spin's sign is transmitted to its neighbor.
\end{proof}

The even sum forgets the neighbor and yields $\cosh$ (building $Z$); the odd sum remembers it
and yields $\sinh$ (building the correlation, propagating the endpoint sign bond by bond).

\section{The Partition Function}

\begin{lemma}[Weight factorization]\label{lem:weightcons}
$\mathrm{weight}(\beta,J,n+1,\,b\!:\!t) = \exp(\beta J\,\sp(b)\,\sp(t_0))\cdot
\mathrm{weight}(\beta,J,n,t)$.
\end{lemma}
\begin{proof}[Proof sketch]
The new chain adds one bond, between $b$ and old site $0$; all others are unchanged. Pull the
first factor out of the product.
\end{proof}

\begin{theorem}[Partition recursion]\label{thm:Zsucc}
$Z(\beta,J,n+1) = (2\cosh(\beta J))\,Z(\beta,J,n)$.
\end{theorem}
\begin{proof}[Proof sketch]
Re-index the sum by the prepended spin $b$ and remainder $t$, use Lemma~\ref{lem:weightcons},
exchange summation order, and apply Lemma~\ref{lem:even} with $c=\beta J$, $y=t_0$; the inner
sum is $2\cosh(\beta J)$ independent of $t$.
\end{proof}

\begin{theorem}[Partition closed form]\label{thm:Zclosed}
$Z(\beta,J,n) = 2\,(2\cosh(\beta J))^{n}$.
\end{theorem}
\begin{proof}[Proof sketch]
Induction: base $n=0$ gives $Z=2$ (two configurations, weight $1$); step uses
Theorem~\ref{thm:Zsucc}.
\end{proof}

\begin{theorem}[Positivity]\label{thm:Zpos}
$Z(\beta,J,n) > 0$, since $\cosh>0$. The normalized correlation is well defined.
\end{theorem}

\section{The Two-Point Correlation Function}

\begin{theorem}[Signed transfer recursion]\label{thm:corrnum-succ}
$\corrNum(\beta,J,n+1) = (2\sinh(\beta J))\,\corrNum(\beta,J,n)$.
\end{theorem}
\begin{proof}[Proof sketch]
Re-index by prepended spin $b$ and remainder $t$, use Lemma~\ref{lem:weightcons}. The endpoint
factor $\sp(s_{n+1})=\sp(t_n)$ is unaffected, while $\sp(b)$ multiplies the Boltzmann factor;
the inner sum over $b$ is the odd identity (Lemma~\ref{lem:odd}) with $c=\beta J$, $y=t_0$,
giving $2\,\sp(t_0)\sinh(\beta J)$. The surviving $\sp(t_0)$ reconstitutes the observable of
the shorter chain.
\end{proof}

\begin{theorem}[Unnormalized closed form]\label{thm:corrnum-closed}
$\corrNum(\beta,J,n) = 2\,(2\sinh(\beta J))^{n}$.
\end{theorem}
\begin{proof}[Proof sketch]
Induction: base $n=0$ gives $\sum_s \sp(s_0)^2 = 2$ by \eqref{eq:star}; step uses
Theorem~\ref{thm:corrnum-succ}.
\end{proof}

\begin{theorem}[Exact correlation]\label{thm:corr-tanh}
$\langle\sigma_0\sigma_n\rangle = (\tanh(\beta J))^{n}$.
\end{theorem}
\begin{proof}[Proof sketch]
Divide Theorem~\ref{thm:corrnum-closed} by Theorem~\ref{thm:Zclosed}; the $2$'s cancel and
$(\sinh/\cosh)^n = (\tanh)^n$. Theorem~\ref{thm:Zpos} legitimizes the division.
\end{proof}

\section{Exponential Decay, Spectral Gap, Absence of Order}

We restrict to $\beta,J>0$.

\begin{lemma}\label{lem:tanh-range}
For $\beta,J>0$, $0 < \tanh(\beta J) < 1$.
\end{lemma}

\begin{theorem}[Exponential-decay form]\label{thm:exp-gap}
For $\beta,J>0$,
$\langle\sigma_0\sigma_n\rangle = \exp(-g(\beta,J)\,n)$ with
$g(\beta,J) = \log\cosh(\beta J)-\log\sinh(\beta J) = \log\coth(\beta J)$.
\end{theorem}
\begin{proof}[Proof sketch]
$(\tanh\beta J)^n = e^{n\log\tanh\beta J}$ (Lemma~\ref{lem:tanh-range} gives $\tanh\beta J>0$),
and $\log\tanh\beta J = \log\sinh\beta J - \log\cosh\beta J = -g$.
\end{proof}

\begin{theorem}[Positive gap]\label{thm:gap-pos}
For $\beta,J>0$, $g(\beta,J)>0$.
\end{theorem}
\begin{proof}[Proof sketch]
$0<\sinh(\beta J)<\cosh(\beta J)\Rightarrow \coth(\beta J)>1\Rightarrow g=\log\coth(\beta J)>0$.
\end{proof}

\begin{theorem}[No long-range order]\label{thm:tendsto}
For $\beta,J>0$, $\displaystyle\lim_{n\to\infty}\langle\sigma_0\sigma_n\rangle = 0$.
\end{theorem}
\begin{proof}[Proof sketch]
By Theorem~\ref{thm:exp-gap} the correlation is $e^{-gn}$ with $g>0$
(Theorem~\ref{thm:gap-pos}), and $e^{-gn}\to0$.
\end{proof}

As $\beta\to\infty$, $\tanh\beta J\to1$, $g\to0$, $\xi\to\infty$: order emerges only at $T=0$.

\section{The Transfer Matrix Viewpoint}

The recursions are matrix-element shadows of the transfer matrix
\[
  T = \begin{pmatrix} e^{\beta J} & e^{-\beta J} \\ e^{-\beta J} & e^{\beta J}\end{pmatrix},
  \qquad \lambda_+ = 2\cosh(\beta J),\quad \lambda_- = 2\sinh(\beta J).
\]
\begin{center}
\begin{tabular}{lll}
\toprule
Object & Combinatorial origin & Spectral meaning \\
\midrule
$Z = 2(2\cosh\beta J)^n$ & even single-bond sum & dominated by $\lambda_+^n$ \\
$\corrNum = 2(2\sinh\beta J)^n$ & odd single-bond sum & $\propto \lambda_-^n$ \\
$\langle\sigma_0\sigma_n\rangle = (\tanh\beta J)^n$ & ratio of the two & $(\lambda_-/\lambda_+)^n$ \\
$g = \log\coth\beta J$ & $-\log\tanh\beta J$ & $\log(\lambda_+/\lambda_-)$ \\
\bottomrule
\end{tabular}
\end{center}
The partition function is governed by the largest eigenvalue, correlations by the eigenvalue
ratio, and the correlation length by the inverse spectral gap.

\section{Discussion and Applications}

The transfer-matrix structure recurs in magnetism and critical phenomena, polymer/biomolecular
helix--coil transitions, Boltzmann machines and Hopfield networks in machine learning, and
lattice field theory (where the spectral gap is a particle mass). The qualitative lesson --
one dimension forbids positive-temperature order because a single domain wall costs only finite
energy while entropy grows with system size -- is the Mermin--Wagner-type intuition.

\paragraph{Comparison with two dimensions.}
The same rule in two dimensions yields, by Onsager, a phase transition at
$T_c = 2/\ln(1+\sqrt2)$, equivalently $\sinh(2\beta_c J)=1$, $\beta_c=\tfrac12\log(1+\sqrt2)$.
The Peierls contour argument yields an ordering threshold $\beta_0=\tfrac12\log 12$; since
$1+\sqrt2<12$, $\beta_c<\beta_0$. In one dimension neither occurs.

\section{Conclusion}

From the bare configuration sum and a two-line induction we obtained the exact endpoint
correlation $\langle\sigma_0\sigma_n\rangle = (\tanh\beta J)^n$, its exponential-decay form
$e^{-gn}$, the identification $g = \log\coth(\beta J) = \log(\lambda_+/\lambda_-)$, strict
positivity of the gap, and the absence of long-range order. The structural key is the
even/odd single-bond dichotomy whose per-bond ratio is $\tanh\beta J = \lambda_-/\lambda_+$.

\section*{Future Directions}
\begin{itemize}
  \item \textbf{Periodic partition function:} $Z_{\mathrm{ring}}(\beta,J,n) = (2\cosh\beta J)^n + (2\sinh\beta J)^n$ for $n\ge1$ (transfer-matrix trace).
  \item \textbf{General two-point function:} $\langle\sigma_a\sigma_b\rangle = (\tanh\beta J)^{b-a}$ (translation invariance).
  \item \textbf{Correlation length asymptotics:} $\xi(\beta,J)\sim \tfrac12 e^{2\beta J}$, i.e. $g = 2e^{-2\beta J}(1+o(1))$ as $\beta\to\infty$.
  \item \textbf{Field-dependent transfer matrix:} $\lambda_+ = e^{\beta J}\cosh(\beta h) + \sqrt{e^{2\beta J}\sinh^2(\beta h) + e^{-2\beta J}}$; joint analyticity of $\log\lambda_+$ and $m(\beta,0)=0$.
  \item \textbf{Peierls meets Onsager:} $\beta_c < \tfrac12\log 12$ with $\beta_c=\tfrac12\log(1+\sqrt2)$, i.e. $1+\sqrt2<12$.
\end{itemize}

