function BruteForceCorrelation(beta, J, n):
    Z <- 0; corrNum <- 0
    for each configuration s in {+1,-1}^(n+1):
        w <- 1
        for i in 0 .. n-1:
            w <- w * exp(beta * J * s[i] * s[i+1])
        Z <- Z + w
        corrNum <- corrNum + s[0] * s[n] * w
    return corrNum / Z

function ClosedFormCorrelation(beta, J, n):
    return tanh(beta * J) ^ n
function PartitionFunction(beta, J, n):
    return 2 * (2 * cosh(beta * J)) ^ n
function UnnormalisedCorrelation(beta, J, n):
    return 2 * (2 * sinh(beta * J)) ^ n

